import { useRef, useEffect } from "react";
import { motion } from "framer-motion";
import { useLanguage } from "@/contexts/LanguageContext";
import { Wine, Beer, Martini, Flame, Leaf, UtensilsCrossed, Sparkles, Droplets, GlassWater, Zap } from "lucide-react";

const CATEGORY_ICONS = {
  signature: Sparkles,
  special: Flame,
  classici: Martini,
  analcolici: Leaf,
  soft_drinks: GlassWater,
  acqua: Droplets,
  taglieri: UtensilsCrossed,
  shots: Zap,
};

export default function CategoryNav({ categories, active, onSelect }) {
  const { t } = useLanguage();
  const scrollRef = useRef(null);

  useEffect(() => {
    if (scrollRef.current) {
      const activeEl = scrollRef.current.querySelector(`[data-cat="${active}"]`);
      if (activeEl) {
        activeEl.scrollIntoView({ behavior: "smooth", block: "nearest", inline: "center" });
      }
    }
  }, [active]);

  return (
    <div className="relative">
      {/* Leaf animation on category change */}
      <motion.div
        key={active}
        className="pointer-events-none absolute -top-6 left-1/2 z-10"
        initial={{ opacity: 0, y: 20, scale: 0.5, rotate: -45 }}
        animate={{ opacity: [0, 0.6, 0], y: [-20, -50], scale: [0.5, 1.2], rotate: [-45, 15] }}
        transition={{ duration: 1.2, ease: "easeOut" }}
      >
        <svg width="32" height="44" viewBox="0 0 32 44" fill="none">
          <path d="M16 0C16 0 30 10 30 22C30 34 16 44 16 44C16 44 2 34 2 22C2 10 16 0 16 0Z" fill="#00FF88" fillOpacity="0.5"/>
          <path d="M16 8V36M16 16L22 12M16 24L10 20" stroke="#0B110D" strokeWidth="1" strokeOpacity="0.4"/>
        </svg>
      </motion.div>

      <nav
        ref={scrollRef}
        className="hide-scrollbar flex gap-2 overflow-x-auto px-1 pb-2 pt-1"
        data-testid="category-nav"
      >
        {categories.map((cat) => {
          const Icon = CATEGORY_ICONS[cat] || Leaf;
          const isActive = cat === active;

          return (
            <motion.button
              key={cat}
              data-cat={cat}
              onClick={() => onSelect(cat)}
              className={`
                relative flex flex-shrink-0 items-center gap-2 rounded-full px-4 py-2.5 font-body text-sm font-medium transition-all
                ${isActive
                  ? "bg-noir-gold text-noir-base shadow-[0_0_20px_rgba(212,175,55,0.3)]"
                  : "border border-noir-gold/15 bg-noir-surface text-noir-text-sec hover:border-noir-gold/30 hover:text-noir-text"
                }
              `}
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              data-testid={`category-btn-${cat}`}
            >
              <Icon size={16} />
              <span>{t.categories[cat] || cat}</span>

              {/* Active leaf accent */}
              {isActive && (
                <motion.svg
                  className="absolute -right-1 -top-1"
                  width="14"
                  height="18"
                  viewBox="0 0 14 18"
                  initial={{ scale: 0, rotate: -90 }}
                  animate={{ scale: 1, rotate: 0 }}
                  transition={{ type: "spring", stiffness: 400, damping: 15 }}
                >
                  <path d="M7 0C7 0 13 4 13 9C13 14 7 18 7 18C7 18 1 14 1 9C1 4 7 0 7 0Z" fill="#00FF88" fillOpacity="0.6"/>
                </motion.svg>
              )}
            </motion.button>
          );
        })}
      </nav>
    </div>
  );
}
