import { motion, AnimatePresence } from "framer-motion";
import { useLanguage } from "@/contexts/LanguageContext";
import { Instagram, X, Sparkles } from "lucide-react";

/* Floating particle for the popup */
function Particle({ delay, x, y, size, color }) {
  return (
    <motion.div
      className="absolute rounded-full"
      style={{ width: size, height: size, left: x, top: y, background: color }}
      initial={{ opacity: 0, scale: 0 }}
      animate={{
        opacity: [0, 0.6, 0],
        scale: [0, 1.5, 0],
        y: [0, -60, -120],
        x: [0, (Math.random() - 0.5) * 40],
      }}
      transition={{ duration: 3, delay, repeat: Infinity, ease: "easeOut" }}
    />
  );
}

export default function PromoPopup({ isOpen, onClose }) {
  const { t } = useLanguage();

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          className="fixed inset-0 z-50 flex items-center justify-center p-4"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          data-testid="promo-popup-overlay"
        >
          {/* Backdrop with blur */}
          <motion.div
            className="absolute inset-0 bg-black/85 backdrop-blur-md"
            onClick={onClose}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          />

          {/* Modal */}
          <motion.div
            className="relative w-full max-w-sm overflow-hidden rounded-2xl border border-noir-gold/30 bg-noir-surface/90 backdrop-blur-xl shadow-noir-deep"
            initial={{ scale: 0.6, opacity: 0, y: 50, rotateX: 15 }}
            animate={{ scale: 1, opacity: 1, y: 0, rotateX: 0 }}
            exit={{ scale: 0.6, opacity: 0, y: 50, rotateX: -15 }}
            transition={{ type: "spring", damping: 20, stiffness: 250 }}
            data-testid="promo-popup-modal"
          >
            {/* Close button */}
            <button
              onClick={onClose}
              className="absolute right-3 top-3 z-10 rounded-full p-1.5 text-noir-text-muted transition-colors hover:bg-noir-elevated hover:text-noir-text"
              data-testid="promo-popup-close"
            >
              <X size={18} />
            </button>

            {/* Animated glow ring */}
            <motion.div
              className="absolute -top-24 left-1/2 h-48 w-48 -translate-x-1/2 rounded-full"
              style={{ background: "radial-gradient(circle, rgba(212,175,55,0.25) 0%, transparent 70%)" }}
              animate={{ scale: [1, 1.3, 1], opacity: [0.5, 0.8, 0.5] }}
              transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
            />

            {/* Floating particles */}
            <Particle delay={0} x="15%" y="70%" size={6} color="rgba(212,175,55,0.5)" />
            <Particle delay={0.5} x="75%" y="60%" size={4} color="rgba(0,255,136,0.4)" />
            <Particle delay={1} x="30%" y="80%" size={5} color="rgba(232,106,51,0.4)" />
            <Particle delay={1.5} x="60%" y="75%" size={3} color="rgba(212,175,55,0.6)" />
            <Particle delay={2} x="85%" y="65%" size={4} color="rgba(0,255,136,0.3)" />
            <Particle delay={0.8} x="45%" y="85%" size={5} color="rgba(212,175,55,0.4)" />

            {/* Decorative animated leaves */}
            <motion.svg
              className="absolute -left-6 top-4 w-28 opacity-15"
              viewBox="0 0 100 150" fill="none"
              animate={{ rotate: [-15, -10, -15], y: [0, -5, 0] }}
              transition={{ duration: 6, repeat: Infinity, ease: "easeInOut" }}
            >
              <path d="M50 0C50 0 85 30 85 75C85 120 50 150 50 150C50 150 15 120 15 75C15 30 50 0 50 0Z" fill="#00FF88"/>
              <path d="M50 20V130M50 50L68 38M50 80L32 68M50 105L65 95" stroke="#0B110D" strokeWidth="1.2" strokeOpacity="0.3"/>
            </motion.svg>
            <motion.svg
              className="absolute -right-4 bottom-8 w-20 opacity-10"
              viewBox="0 0 100 150" fill="none"
              animate={{ rotate: [20, 15, 20], y: [0, -4, 0] }}
              transition={{ duration: 7, repeat: Infinity, ease: "easeInOut", delay: 2 }}
            >
              <path d="M50 0C50 0 85 30 85 75C85 120 50 150 50 150C50 150 15 120 15 75C15 30 50 0 50 0Z" fill="#D4AF37"/>
            </motion.svg>

            <div className="relative px-6 pb-8 pt-10 text-center">
              {/* Animated sparkle icon */}
              <motion.div
                className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full border border-noir-gold/40 bg-noir-gold/10"
                animate={{ rotate: [0, 8, -8, 0], scale: [1, 1.05, 1] }}
                transition={{ duration: 4, repeat: Infinity, ease: "easeInOut" }}
              >
                <motion.div
                  animate={{ rotate: [0, 360] }}
                  transition={{ duration: 8, repeat: Infinity, ease: "linear" }}
                >
                  <Sparkles className="text-noir-gold" size={28} />
                </motion.div>
              </motion.div>

              {/* Title with stagger */}
              <motion.p
                className="mb-1 text-xs font-body uppercase tracking-[0.3em] text-noir-gold"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.3 }}
              >
                {t.promo.title}
              </motion.p>

              <motion.h2
                className="mb-4 font-heading text-5xl font-bold text-noir-text text-shadow-noir"
                initial={{ opacity: 0, y: 15 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.4, type: "spring", stiffness: 200 }}
                data-testid="promo-discount-text"
              >
                {t.promo.discount}
              </motion.h2>

              <motion.p
                className="mb-3 text-sm text-noir-text-sec"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.6 }}
              >
                {t.promo.description}
              </motion.p>

              {/* Instagram tag with pulse */}
              <motion.div
                className="mx-auto mb-4 inline-flex items-center gap-2 rounded-full border border-noir-gold/30 bg-noir-gold/10 px-5 py-2.5"
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ delay: 0.7, type: "spring", stiffness: 300 }}
                whileHover={{ scale: 1.08, borderColor: "rgba(212,175,55,0.6)" }}
                whileTap={{ scale: 0.95 }}
              >
                <motion.div
                  animate={{ scale: [1, 1.2, 1] }}
                  transition={{ duration: 2, repeat: Infinity }}
                >
                  <Instagram className="text-noir-gold" size={20} />
                </motion.div>
                <span className="font-heading text-xl font-semibold text-noir-gold" data-testid="promo-instagram-tag">
                  {t.promo.tag}
                </span>
              </motion.div>

              <motion.p
                className="mb-6 text-xs text-noir-text-muted"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 0.9 }}
              >
                {t.promo.instruction}
              </motion.p>

              <motion.button
                onClick={onClose}
                className="w-full rounded-full bg-noir-gold px-6 py-3 font-body text-sm font-semibold uppercase tracking-widest text-noir-base transition-colors hover:bg-noir-gold-hover"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 1 }}
                whileHover={{ scale: 1.03, boxShadow: "0 0 30px rgba(212,175,55,0.3)" }}
                whileTap={{ scale: 0.97 }}
                data-testid="promo-popup-cta"
              >
                {t.promo.cta}
              </motion.button>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}
