import { useLanguage } from "@/contexts/LanguageContext";
import { motion } from "framer-motion";
import { Globe } from "lucide-react";

export default function LanguageToggle() {
  const { t, toggleLang, lang } = useLanguage();

  return (
    <motion.button
      onClick={toggleLang}
      className="flex items-center gap-1.5 rounded-full border border-noir-gold/20 bg-noir-surface/80 px-3 py-1.5 text-xs font-medium text-noir-text-sec backdrop-blur-sm transition-colors hover:border-noir-gold/40 hover:text-noir-text"
      whileHover={{ scale: 1.05 }}
      whileTap={{ scale: 0.95 }}
      data-testid="language-toggle"
    >
      <Globe size={13} />
      <span className="uppercase tracking-wider">{t.language}</span>
    </motion.button>
  );
}
