import { motion } from "framer-motion";
import { useLanguage } from "@/contexts/LanguageContext";
import { AlertTriangle } from "lucide-react";
import { Badge } from "@/components/ui/badge";

export default function MenuItemCard({ item, index }) {
  const { lang, t } = useLanguage();

  const name = lang === "it" ? item.name_it : item.name_en;
  const desc = lang === "it" ? item.description_it : item.description_en;

  return (
    <motion.div
      className="group relative rounded-2xl border border-noir-gold/10 bg-noir-surface/60 p-4 backdrop-blur-sm transition-all shadow-noir-card hover:border-noir-gold/25 hover:shadow-noir-glow"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: index * 0.05, duration: 0.4 }}
      whileHover={{ y: -2 }}
      data-testid={`menu-item-${item.id}`}
    >
      <div className="flex items-start justify-between gap-3">
        <div className="flex-1 min-w-0">
          <h3 className="font-heading text-lg font-semibold text-noir-text group-hover:text-noir-gold transition-colors">
            {name}
          </h3>
          {desc && (
            <p className="mt-1 text-sm text-noir-text-muted leading-relaxed line-clamp-2">
              {desc}
            </p>
          )}

          {/* Allergens */}
          {item.allergens && item.allergens.length > 0 && (
            <div className="mt-2 flex flex-wrap gap-1.5">
              {item.allergens.map((allergen) => (
                <span
                  key={allergen}
                  className="inline-flex items-center gap-1 rounded-full bg-noir-ember/10 px-2 py-0.5 text-[10px] font-medium uppercase tracking-wider text-noir-ember"
                >
                  <AlertTriangle size={9} />
                  {t.allergens[allergen] || allergen}
                </span>
              ))}
            </div>
          )}
        </div>

        {/* Price */}
        <div className="flex flex-col items-end flex-shrink-0">
          <span className="font-heading text-xl font-bold text-noir-gold" data-testid={`menu-item-price-${item.id}`}>
            {item.price.toFixed(2)}
          </span>
          {item.price_bottle && (
            <span className="mt-0.5 text-[10px] uppercase tracking-wider text-noir-text-muted">
              {t.menu.bottle}: {item.price_bottle.toFixed(2)}
            </span>
          )}
        </div>
      </div>

      {/* Cocktail of the day badge */}
      {item.is_cocktail_of_day && (
        <Badge className="absolute -top-2 right-3 border-noir-gold/30 bg-noir-gold/20 text-noir-gold text-[10px] uppercase tracking-wider" data-testid="cocktail-of-day-badge">
          {t.menu.cocktailOfDay}
        </Badge>
      )}
    </motion.div>
  );
}
