import { useState, useEffect, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import axios from "axios";
import { useLanguage } from "@/contexts/LanguageContext";
import PromoPopup from "@/components/PromoPopup";
import CategoryNav from "@/components/CategoryNav";
import MenuItemCard from "@/components/MenuItemCard";
import CocktailOfDay from "@/components/CocktailOfDay";
import AllergenFilter from "@/components/AllergenFilter";
import BackgroundLeaves from "@/components/BackgroundLeaves";
import LanguageToggle from "@/components/LanguageToggle";
import { MapPin, Clock, Settings, Info, Phone, Instagram, Calendar } from "lucide-react";
import { useNavigate } from "react-router-dom";

const API = `${process.env.REACT_APP_BACKEND_URL || ""}/api`;

export default function MenuPage() {
  const { t, lang } = useLanguage();
  const navigate = useNavigate();
  const [showPromo, setShowPromo] = useState(false);
  const [categories, setCategories] = useState([]);
  const [activeCategory, setActiveCategory] = useState("");
  const [menuItems, setMenuItems] = useState([]);
  const [cocktailOfDay, setCocktailOfDay] = useState(null);
  const [allergenFilters, setAllergenFilters] = useState([]);
  const [loading, setLoading] = useState(true);
  const [venueSettings, setVenueSettings] = useState(null);
  const [events, setEvents] = useState([]);

  useEffect(() => {
    const timer = setTimeout(() => setShowPromo(true), 800);
    return () => clearTimeout(timer);
  }, []);

  const closePromo = () => {
    setShowPromo(false);
  };

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [catRes, codRes, settRes, evtRes] = await Promise.all([
          axios.get(`${API}/menu/categories`),
          axios.get(`${API}/menu/cocktail-of-day`),
          axios.get(`${API}/settings`),
          axios.get(`${API}/events`),
        ]);
        setCategories(catRes.data);
        setCocktailOfDay(codRes.data);
        setVenueSettings(settRes.data);
        setEvents(evtRes.data);
        if (catRes.data.length > 0) {
          setActiveCategory(catRes.data[0]);
        }
      } catch (e) {
        console.error("Failed to fetch menu data", e);
      }
    };
    fetchData();
  }, []);

  const fetchMenuItems = useCallback(async () => {
    if (!activeCategory) return;
    setLoading(true);
    try {
      const res = await axios.get(`${API}/menu`, { params: { category: activeCategory } });
      setMenuItems(res.data);
    } catch (e) {
      console.error("Failed to fetch menu items", e);
    } finally {
      setLoading(false);
    }
  }, [activeCategory]);

  useEffect(() => {
    fetchMenuItems();
  }, [fetchMenuItems]);

  const filteredItems = allergenFilters.length > 0
    ? menuItems.filter(
        (item) => !item.allergens.some((a) => allergenFilters.includes(a))
      )
    : menuItems;

  const toggleAllergen = (a) => {
    setAllergenFilters((prev) =>
      prev.includes(a) ? prev.filter((x) => x !== a) : [...prev, a]
    );
  };

  return (
    <div className="relative min-h-screen" data-testid="menu-page">
      <BackgroundLeaves />
      <PromoPopup isOpen={showPromo} onClose={closePromo} />

      {/* Fixed background — Amazon jungle (vivid) */}
      <div className="fixed inset-0 z-0">
        <img
          src="/jungle-bg.png"
          alt=""
          className="h-full w-full object-cover"
          style={{ filter: "saturate(1.1) brightness(0.55)" }}
        />
        <div className="absolute inset-0" style={{ background: "linear-gradient(to bottom, rgba(11,17,13,0.55) 0%, rgba(11,17,13,0.35) 40%, rgba(11,17,13,0.6) 100%)" }} />
      </div>

      <div className="relative z-10 mx-auto max-w-lg px-4 pb-12">
        {/* Header */}
        <header className="pb-6 pt-8">
          <div className="flex items-start justify-between">
            <motion.div
              initial={{ opacity: 0, x: -30 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1] }}
            >
              <motion.h1
                className="font-heading text-5xl font-bold tracking-tight text-noir-text text-shadow-noir"
                data-testid="hero-title"
              >
                {t.hero.title}
              </motion.h1>
              <motion.p
                className="mt-1 text-xs uppercase tracking-[0.3em] text-noir-gold"
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.3 }}
              >
                {t.hero.subtitle}
              </motion.p>
            </motion.div>

            <div className="flex items-center gap-2">
              <LanguageToggle />
              <motion.button
                onClick={() => navigate("/about")}
                className="rounded-full border border-noir-gold/15 bg-noir-surface/80 p-2 text-noir-text-muted backdrop-blur-sm transition-colors hover:text-noir-gold"
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                data-testid="about-link"
              >
                <Info size={16} />
              </motion.button>
              <motion.button
                onClick={() => navigate("/admin")}
                className="rounded-full border border-noir-gold/15 bg-noir-surface/80 p-2 text-noir-text-muted backdrop-blur-sm transition-colors hover:text-noir-gold"
                whileHover={{ scale: 1.1, rotate: 90 }}
                whileTap={{ scale: 0.9 }}
                data-testid="admin-link"
              >
                <Settings size={16} />
              </motion.button>
            </div>
          </div>

          <motion.div
            className="mt-4 flex flex-col gap-1.5"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.4 }}
          >
            {/* Open/Closed status */}
            {venueSettings && (
              <motion.div
                className={`mb-1 inline-flex items-center gap-1.5 self-start rounded-full px-3 py-1 text-[10px] font-semibold uppercase tracking-wider ${
                  venueSettings.is_open
                    ? "bg-noir-neon/15 text-noir-neon border border-noir-neon/30"
                    : "bg-red-500/15 text-red-400 border border-red-500/30"
                }`}
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                transition={{ delay: 0.5, type: "spring" }}
                data-testid="venue-status-badge"
              >
                <span className={`h-1.5 w-1.5 rounded-full ${venueSettings.is_open ? "bg-noir-neon animate-pulse" : "bg-red-400"}`} />
                {venueSettings.is_open ? (lang === "it" ? "Aperto" : "Open") : (lang === "it" ? "Chiuso" : "Closed")}
              </motion.div>
            )}
            <div className="flex items-center gap-2 text-noir-text-muted">
              <MapPin size={13} className="text-noir-gold" />
              <span className="text-xs">{venueSettings?.address || t.hero.address}</span>
            </div>
            <div className="flex items-center gap-2 text-noir-text-muted">
              <Clock size={13} className="text-noir-gold" />
              <span className="text-xs">
                {venueSettings ? `${venueSettings.opening_time} - ${venueSettings.closing_time}` : t.hero.hours}
              </span>
            </div>
            {venueSettings?.phone && (
              <motion.div className="flex items-center gap-2 text-noir-text-muted" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.6 }}>
                <Phone size={13} className="text-noir-gold" />
                <a href={`tel:${venueSettings.phone}`} className="text-xs hover:text-noir-gold transition-colors">{venueSettings.phone}</a>
              </motion.div>
            )}
            {venueSettings?.instagram && (
              <motion.div className="flex items-center gap-2 text-noir-text-muted" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.7 }}>
                <Instagram size={13} className="text-noir-gold" />
                <a href={`https://instagram.com/${venueSettings.instagram.replace('@','')}`} target="_blank" rel="noopener noreferrer" className="text-xs hover:text-noir-gold transition-colors">{venueSettings.instagram}</a>
              </motion.div>
            )}
          </motion.div>
        </header>

        {/* Cocktail of the Day */}
        {cocktailOfDay && (
          <div className="mb-6">
            <CocktailOfDay item={cocktailOfDay} />
          </div>
        )}

        {/* Category Navigation */}
        {categories.length > 0 && (
          <div className="mb-4">
            <CategoryNav
              categories={categories}
              active={activeCategory}
              onSelect={setActiveCategory}
            />
          </div>
        )}

        {/* Allergen Filter */}
        <div className="mb-5">
          <AllergenFilter
            activeFilters={allergenFilters}
            onToggle={toggleAllergen}
            onClear={() => setAllergenFilters([])}
          />
        </div>

        {/* Separator with category name */}
        <motion.div
          key={activeCategory}
          className="mb-4 flex items-center gap-3"
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
        >
          <div className="h-px flex-1 bg-gradient-to-r from-noir-gold/30 to-transparent" />
          <h2 className="font-heading text-lg uppercase tracking-[0.2em] text-noir-gold" data-testid="active-category-title">
            {t.categories[activeCategory] || activeCategory}
          </h2>
          <div className="h-px flex-1 bg-gradient-to-l from-noir-gold/30 to-transparent" />
        </motion.div>

        {/* Menu Items */}
        <AnimatePresence mode="wait">
          <motion.div
            key={activeCategory + allergenFilters.join(",")}
            className="flex flex-col gap-3"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            data-testid="menu-items-list"
          >
            {loading ? (
              <div className="flex justify-center py-12">
                <motion.div
                  className="h-8 w-8 rounded-full border-2 border-noir-gold/30 border-t-noir-gold"
                  animate={{ rotate: 360 }}
                  transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                />
              </div>
            ) : filteredItems.length > 0 ? (
              filteredItems.map((item, i) => (
                <MenuItemCard key={item.id} item={item} index={i} />
              ))
            ) : (
              <p className="py-8 text-center text-sm text-noir-text-muted">
                {t.menu.noItems}
              </p>
            )}
          </motion.div>
        </AnimatePresence>

        {/* Events Section */}
        {events.length > 0 && (
          <motion.div
            className="mt-10"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.4 }}
            data-testid="events-section"
          >
            <div className="mb-4 flex items-center gap-3">
              <div className="h-px flex-1 bg-gradient-to-r from-noir-gold/30 to-transparent" />
              <h2 className="flex items-center gap-2 font-heading text-lg uppercase tracking-[0.2em] text-noir-gold">
                <Calendar size={16} />
                {lang === "it" ? "Eventi" : "Events"}
              </h2>
              <div className="h-px flex-1 bg-gradient-to-l from-noir-gold/30 to-transparent" />
            </div>
            <div className="space-y-3">
              {events.map((event, i) => (
                <motion.div
                  key={event.id}
                  className="rounded-2xl border border-noir-gold/15 bg-noir-surface/60 p-4 shadow-noir-card backdrop-blur-sm"
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: i * 0.1 }}
                  whileHover={{ y: -2, borderColor: "rgba(212,175,55,0.3)" }}
                >
                  <div className="flex items-start justify-between gap-3">
                    <div className="flex-1">
                      <h3 className="font-heading text-lg font-semibold text-noir-text">
                        {lang === "it" ? event.title_it : (event.title_en || event.title_it)}
                      </h3>
                      <p className="mt-1 text-sm text-noir-text-muted leading-relaxed">
                        {lang === "it" ? event.description_it : (event.description_en || event.description_it)}
                      </p>
                    </div>
                  </div>
                  {(event.date || event.time) && (
                    <div className="mt-2 flex items-center gap-3 text-xs text-noir-gold">
                      {event.date && (
                        <span className="flex items-center gap-1">
                          <Calendar size={11} />
                          {new Date(event.date + "T00:00").toLocaleDateString(lang === "it" ? "it-IT" : "en-US", { day: "numeric", month: "long" })}
                        </span>
                      )}
                      {event.time && (
                        <span className="flex items-center gap-1">
                          <Clock size={11} />
                          {event.time}
                        </span>
                      )}
                    </div>
                  )}
                </motion.div>
              ))}
            </div>
          </motion.div>
        )}

        {/* Footer */}
        <motion.footer
          className="mt-12 border-t border-noir-gold/10 pt-6 text-center"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.5 }}
        >
          <p className="font-heading text-xl text-noir-text">NOIR 36</p>
          <p className="mt-1 text-xs text-noir-text-muted">{t.hero.address}</p>
          <p className="text-xs text-noir-text-muted">{t.hero.hours}</p>
          <div className="mt-3 flex items-center justify-center gap-2">
            <a
              href="https://instagram.com/noir36"
              target="_blank"
              rel="noopener noreferrer"
              className="text-xs text-noir-gold transition-colors hover:text-noir-gold-hover"
              data-testid="instagram-link"
            >
              @noir36
            </a>
          </div>
        </motion.footer>
      </div>
    </div>
  );
}
