import { useState, useEffect, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import axios from "axios";
import { useAuth } from "@/contexts/AuthContext";
import { useLanguage } from "@/contexts/LanguageContext";
import { useNavigate } from "react-router-dom";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { ArrowLeft, Plus, Pencil, Trash2, LogOut, Save, X, Sparkles, Settings2, Store, Calendar, Star } from "lucide-react";
import LanguageToggle from "@/components/LanguageToggle";
import BackgroundLeaves from "@/components/BackgroundLeaves";

const API = `${process.env.REACT_APP_BACKEND_URL || ""}/api`;
const CATEGORIES = ["signature", "special", "classici", "analcolici", "soft_drinks", "acqua", "taglieri", "shots"];
const ALLERGENS = ["glutine", "lattosio", "frutta_a_guscio", "uova", "solfiti", "sesamo"];

function formatApiError(detail) {
  if (!detail) return "Errore sconosciuto";
  if (typeof detail === "string") return detail;
  if (Array.isArray(detail)) return detail.map((e) => e?.msg || JSON.stringify(e)).join(" ");
  return String(detail);
}

export default function AdminPage() {
  const { user, login, logout, authHeader, loading: authLoading } = useAuth();
  const { t } = useLanguage();
  const navigate = useNavigate();

  // Login state
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loginError, setLoginError] = useState("");
  const [loggingIn, setLoggingIn] = useState(false);

  // Active tab
  const [activeTab, setActiveTab] = useState("menu");

  // Menu state
  const [menuItems, setMenuItems] = useState([]);
  const [editingItem, setEditingItem] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState({
    name_it: "", name_en: "", description_it: "", description_en: "",
    price: "", price_bottle: "", category: "cocktail", allergens: [],
    is_cocktail_of_day: false, is_available: true, order: 0,
  });

  // Settings state
  const [settings, setSettings] = useState(null);
  const [savingSettings, setSavingSettings] = useState(false);

  // Events state
  const [events, setEvents] = useState([]);
  const [editingEvent, setEditingEvent] = useState(null);
  const [showEventForm, setShowEventForm] = useState(false);
  const [savingEvent, setSavingEvent] = useState(false);
  const [eventForm, setEventForm] = useState({ title_it: "", title_en: "", description_it: "", description_en: "", date: "", time: "", is_active: true });

  const fetchItems = useCallback(async () => {
    try {
      const res = await axios.get(`${API}/admin/menu`, { headers: authHeader() });
      setMenuItems(res.data);
    } catch (e) { console.error(e); }
  }, [authHeader]);

  const fetchSettings = useCallback(async () => {
    try {
      const res = await axios.get(`${API}/admin/settings`, { headers: authHeader() });
      setSettings(res.data);
    } catch (e) { console.error(e); }
  }, [authHeader]);

  const fetchEvents = useCallback(async () => {
    try {
      const res = await axios.get(`${API}/admin/events`, { headers: authHeader() });
      setEvents(res.data);
    } catch (e) { console.error(e); }
  }, [authHeader]);

  useEffect(() => {
    if (user) { fetchItems(); fetchSettings(); fetchEvents(); }
  }, [user, fetchItems, fetchSettings, fetchEvents]);

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoginError("");
    setLoggingIn(true);
    try { await login(email, password); }
    catch (err) { setLoginError(formatApiError(err.response?.data?.detail) || err.message); }
    finally { setLoggingIn(false); }
  };

  // Menu CRUD
  const openCreateForm = () => {
    setEditingItem(null);
    setFormData({ name_it: "", name_en: "", description_it: "", description_en: "", price: "", price_bottle: "", category: "cocktail", allergens: [], is_cocktail_of_day: false, is_available: true, order: 0 });
    setShowForm(true);
  };

  const openEditForm = (item) => {
    setEditingItem(item);
    setFormData({
      name_it: item.name_it, name_en: item.name_en,
      description_it: item.description_it || "", description_en: item.description_en || "",
      price: String(item.price), price_bottle: item.price_bottle ? String(item.price_bottle) : "",
      category: item.category, allergens: item.allergens || [],
      is_cocktail_of_day: item.is_cocktail_of_day || false,
      is_available: item.is_available !== false, order: item.order || 0,
    });
    setShowForm(true);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      const payload = { ...formData, price: parseFloat(formData.price), price_bottle: formData.price_bottle ? parseFloat(formData.price_bottle) : null, order: parseInt(formData.order, 10) || 0 };
      if (editingItem) await axios.put(`${API}/admin/menu/${editingItem.id}`, payload, { headers: authHeader() });
      else await axios.post(`${API}/admin/menu`, payload, { headers: authHeader() });
      setShowForm(false);
      fetchItems();
    } catch (e) { alert(formatApiError(e.response?.data?.detail)); }
    finally { setSaving(false); }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Eliminare questo elemento?")) return;
    try { await axios.delete(`${API}/admin/menu/${id}`, { headers: authHeader() }); fetchItems(); }
    catch (e) { alert(formatApiError(e.response?.data?.detail)); }
  };

  const toggleAllergen = (a) => setFormData((p) => ({ ...p, allergens: p.allergens.includes(a) ? p.allergens.filter((x) => x !== a) : [...p.allergens, a] }));

  // Settings save
  const handleSaveSettings = async () => {
    setSavingSettings(true);
    try {
      const res = await axios.put(`${API}/admin/settings`, settings, { headers: authHeader() });
      setSettings(res.data);
    } catch (e) { alert(formatApiError(e.response?.data?.detail)); }
    finally { setSavingSettings(false); }
  };

  // Events CRUD
  const openEventCreate = () => {
    setEditingEvent(null);
    setEventForm({ title_it: "", title_en: "", description_it: "", description_en: "", date: "", time: "", is_active: true });
    setShowEventForm(true);
  };
  const openEventEdit = (ev) => {
    setEditingEvent(ev);
    setEventForm({ title_it: ev.title_it, title_en: ev.title_en || "", description_it: ev.description_it || "", description_en: ev.description_en || "", date: ev.date || "", time: ev.time || "", is_active: ev.is_active !== false });
    setShowEventForm(true);
  };
  const handleSaveEvent = async () => {
    setSavingEvent(true);
    try {
      if (editingEvent) await axios.put(`${API}/admin/events/${editingEvent.id}`, eventForm, { headers: authHeader() });
      else await axios.post(`${API}/admin/events`, eventForm, { headers: authHeader() });
      setShowEventForm(false);
      fetchEvents();
    } catch (e) { alert(formatApiError(e.response?.data?.detail)); }
    finally { setSavingEvent(false); }
  };
  const handleDeleteEvent = async (id) => {
    if (!window.confirm("Eliminare questo evento?")) return;
    try { await axios.delete(`${API}/admin/events/${id}`, { headers: authHeader() }); fetchEvents(); }
    catch (e) { alert(formatApiError(e.response?.data?.detail)); }
  };

  // Cocktail of the day
  const setCocktailOfDay = async (itemId) => {
    try {
      await axios.put(`${API}/admin/cocktail-of-day/${itemId}`, {}, { headers: authHeader() });
      fetchItems();
    } catch (e) { alert(formatApiError(e.response?.data?.detail)); }
  };

  if (authLoading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-noir-base">
        <motion.div className="h-8 w-8 rounded-full border-2 border-noir-gold/30 border-t-noir-gold" animate={{ rotate: 360 }} transition={{ duration: 1, repeat: Infinity, ease: "linear" }} />
      </div>
    );
  }

  // Login form
  if (!user) {
    return (
      <div className="relative flex min-h-screen items-center justify-center" data-testid="admin-login-page">
        <BackgroundLeaves />
        <motion.div className="relative z-10 w-full max-w-sm rounded-2xl border border-noir-gold/20 bg-noir-surface/90 p-8 backdrop-blur-xl shadow-noir-deep" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
          <button onClick={() => navigate("/")} className="mb-6 flex items-center gap-2 text-sm text-noir-text-muted transition-colors hover:text-noir-text" data-testid="admin-back-to-menu">
            <ArrowLeft size={16} /> {t.nav.menu}
          </button>
          <h1 className="mb-1 font-heading text-3xl font-bold text-noir-text">{t.admin.title}</h1>
          <p className="mb-6 text-sm text-noir-text-muted">NOIR 36</p>
          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <Label className="text-noir-text-sec text-xs uppercase tracking-wider">{t.admin.email}</Label>
              <Input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text placeholder:text-noir-text-muted focus:border-noir-gold/40" required data-testid="admin-email-input" />
            </div>
            <div>
              <Label className="text-noir-text-sec text-xs uppercase tracking-wider">{t.admin.password}</Label>
              <Input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text placeholder:text-noir-text-muted focus:border-noir-gold/40" required data-testid="admin-password-input" />
            </div>
            {loginError && <p className="text-sm text-red-400" data-testid="admin-login-error">{loginError}</p>}
            <motion.button type="submit" disabled={loggingIn} className="w-full rounded-full bg-noir-gold px-6 py-3 font-body text-sm font-semibold uppercase tracking-widest text-noir-base hover:bg-noir-gold-hover disabled:opacity-50" whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }} data-testid="admin-login-button">
              {loggingIn ? "..." : t.admin.login}
            </motion.button>
          </form>
        </motion.div>
      </div>
    );
  }

  // Admin Dashboard
  const groupedItems = CATEGORIES.reduce((acc, cat) => { acc[cat] = menuItems.filter((i) => i.category === cat); return acc; }, {});

  return (
    <div className="relative min-h-screen" data-testid="admin-dashboard">
      <BackgroundLeaves />
      <div className="relative z-10 mx-auto max-w-2xl px-4 pb-12">
        {/* Header */}
        <header className="flex items-center justify-between pb-4 pt-8">
          <div className="flex items-center gap-3">
            <button onClick={() => navigate("/")} className="rounded-full border border-noir-gold/15 bg-noir-surface p-2 text-noir-text-muted hover:text-noir-text" data-testid="admin-back-btn">
              <ArrowLeft size={16} />
            </button>
            <div>
              <h1 className="font-heading text-2xl font-bold text-noir-text">{t.admin.title}</h1>
              <p className="text-xs text-noir-text-muted">{user.email}</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <LanguageToggle />
            <motion.button onClick={logout} className="flex items-center gap-1.5 rounded-full border border-red-500/20 bg-noir-surface px-3 py-1.5 text-xs text-red-400 hover:bg-red-500/10" whileHover={{ scale: 1.05 }} data-testid="admin-logout-button">
              <LogOut size={13} /> {t.admin.logout}
            </motion.button>
          </div>
        </header>

        {/* Tabs */}
        <div className="mb-6 flex gap-2">
          {[{ id: "menu", icon: Sparkles, label: "Menu" }, { id: "events", icon: Calendar, label: "Eventi" }, { id: "settings", icon: Settings2, label: t.admin.settings || "Impostazioni" }].map((tab) => (
            <motion.button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center gap-2 rounded-full px-4 py-2 text-sm font-medium transition-all ${
                activeTab === tab.id ? "bg-noir-gold text-noir-base" : "border border-noir-gold/15 bg-noir-surface text-noir-text-sec hover:text-noir-text"
              }`}
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              data-testid={`admin-tab-${tab.id}`}
            >
              <tab.icon size={14} /> {tab.label}
            </motion.button>
          ))}
        </div>

        {/* ===== MENU TAB ===== */}
        {activeTab === "menu" && (
          <>
            <motion.button onClick={openCreateForm} className="mb-6 flex items-center gap-2 rounded-full bg-noir-gold px-5 py-2.5 font-body text-sm font-semibold text-noir-base hover:bg-noir-gold-hover" whileHover={{ scale: 1.03 }} whileTap={{ scale: 0.97 }} data-testid="admin-add-item-btn">
              <Plus size={16} /> {t.admin.addItem}
            </motion.button>

            {CATEGORIES.map((cat) => (
              <div key={cat} className="mb-6">
                <h2 className="mb-3 font-heading text-lg uppercase tracking-[0.15em] text-noir-gold">
                  {t.categories[cat]} ({groupedItems[cat]?.length || 0})
                </h2>
                <div className="space-y-2">
                  {(groupedItems[cat] || []).map((item) => (
                    <motion.div key={item.id} className="flex items-center justify-between rounded-xl border border-noir-gold/10 bg-noir-surface/60 p-3" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="font-heading text-base text-noir-text truncate">{item.name_it}</span>
                          {item.is_cocktail_of_day && <Sparkles size={12} className="text-noir-gold flex-shrink-0" />}
                          {!item.is_available && <span className="text-[10px] text-red-400 uppercase">N/D</span>}
                        </div>
                        <span className="text-xs text-noir-text-muted">{item.name_en}</span>
                      </div>
                      <div className="flex items-center gap-1 flex-shrink-0 ml-2">
                        <span className="font-heading text-base text-noir-gold">{item.price.toFixed(2)}</span>
                        <button onClick={() => setCocktailOfDay(item.id)} className={`rounded-lg p-1.5 transition-colors ${item.is_cocktail_of_day ? "text-noir-gold" : "text-noir-text-muted hover:text-noir-gold"}`} title="Cocktail del Giorno" data-testid={`admin-star-${item.id}`}><Star size={14} fill={item.is_cocktail_of_day ? "#D4AF37" : "none"} /></button>
                        <button onClick={() => openEditForm(item)} className="rounded-lg p-1.5 text-noir-text-muted hover:bg-noir-elevated hover:text-noir-gold" data-testid={`admin-edit-${item.id}`}><Pencil size={14} /></button>
                        <button onClick={() => handleDelete(item.id)} className="rounded-lg p-1.5 text-noir-text-muted hover:bg-red-500/10 hover:text-red-400" data-testid={`admin-delete-${item.id}`}><Trash2 size={14} /></button>
                      </div>
                    </motion.div>
                  ))}
                </div>
              </div>
            ))}
          </>
        )}

        {/* ===== EVENTS TAB ===== */}
        {activeTab === "events" && (
          <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="space-y-4">
            <motion.button onClick={openEventCreate} className="mb-4 flex items-center gap-2 rounded-full bg-noir-gold px-5 py-2.5 font-body text-sm font-semibold text-noir-base hover:bg-noir-gold-hover" whileHover={{ scale: 1.03 }} data-testid="admin-add-event-btn">
              <Plus size={16} /> Aggiungi Evento
            </motion.button>

            {events.length === 0 && <p className="py-8 text-center text-sm text-noir-text-muted">Nessun evento</p>}

            {events.map((ev) => (
              <motion.div key={ev.id} className="rounded-2xl border border-noir-gold/10 bg-noir-surface/60 p-4 shadow-noir-card" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                <div className="flex items-start justify-between">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <h3 className="font-heading text-base font-semibold text-noir-text">{ev.title_it}</h3>
                      {!ev.is_active && <span className="text-[10px] text-red-400 uppercase border border-red-400/30 px-1.5 py-0.5 rounded-full">Nascosto</span>}
                    </div>
                    <p className="mt-0.5 text-xs text-noir-text-muted line-clamp-2">{ev.description_it}</p>
                    {(ev.date || ev.time) && (
                      <p className="mt-1 text-xs text-noir-gold">{ev.date} {ev.time && `- ${ev.time}`}</p>
                    )}
                  </div>
                  <div className="flex items-center gap-1 flex-shrink-0 ml-2">
                    <button onClick={() => openEventEdit(ev)} className="rounded-lg p-1.5 text-noir-text-muted hover:text-noir-gold" data-testid={`admin-edit-event-${ev.id}`}><Pencil size={14} /></button>
                    <button onClick={() => handleDeleteEvent(ev.id)} className="rounded-lg p-1.5 text-noir-text-muted hover:text-red-400" data-testid={`admin-delete-event-${ev.id}`}><Trash2 size={14} /></button>
                  </div>
                </div>
              </motion.div>
            ))}
          </motion.div>
        )}

        {/* ===== SETTINGS TAB ===== */}
        {activeTab === "settings" && settings && (
          <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="space-y-6">
            {/* Venue Status */}
            <div className="rounded-2xl border border-noir-gold/15 bg-noir-surface/60 p-5 shadow-noir-card">
              <div className="flex items-center gap-3 mb-4">
                <Store size={18} className="text-noir-gold" />
                <h3 className="font-heading text-lg font-semibold text-noir-text">Stato Locale</h3>
              </div>
              <div className="flex items-center gap-3">
                <Switch
                  checked={settings.is_open}
                  onCheckedChange={(v) => setSettings({ ...settings, is_open: v })}
                  data-testid="settings-is-open"
                />
                <span className={`text-sm font-medium ${settings.is_open ? "text-noir-neon" : "text-red-400"}`}>
                  {settings.is_open ? "Aperto" : "Chiuso"}
                </span>
              </div>
            </div>

            {/* Hours */}
            <div className="rounded-2xl border border-noir-gold/15 bg-noir-surface/60 p-5 shadow-noir-card">
              <h3 className="font-heading text-lg font-semibold text-noir-text mb-4">Orari</h3>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-noir-text-sec text-xs uppercase tracking-wider">Apertura</Label>
                  <Input type="time" value={settings.opening_time} onChange={(e) => setSettings({ ...settings, opening_time: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="settings-opening-time" />
                </div>
                <div>
                  <Label className="text-noir-text-sec text-xs uppercase tracking-wider">Chiusura</Label>
                  <Input type="time" value={settings.closing_time} onChange={(e) => setSettings({ ...settings, closing_time: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="settings-closing-time" />
                </div>
              </div>
            </div>

            {/* Contact Info */}
            <div className="rounded-2xl border border-noir-gold/15 bg-noir-surface/60 p-5 shadow-noir-card">
              <h3 className="font-heading text-lg font-semibold text-noir-text mb-4">Contatti</h3>
              <div className="space-y-3">
                <div>
                  <Label className="text-noir-text-sec text-xs uppercase tracking-wider">Instagram</Label>
                  <Input value={settings.instagram} onChange={(e) => setSettings({ ...settings, instagram: e.target.value })} placeholder="@noir36" className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="settings-instagram" />
                </div>
                <div>
                  <Label className="text-noir-text-sec text-xs uppercase tracking-wider">Telefono</Label>
                  <Input value={settings.phone} onChange={(e) => setSettings({ ...settings, phone: e.target.value })} placeholder="+39 06 1234567" className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="settings-phone" />
                </div>
                <div>
                  <Label className="text-noir-text-sec text-xs uppercase tracking-wider">Email</Label>
                  <Input type="email" value={settings.email} onChange={(e) => setSettings({ ...settings, email: e.target.value })} placeholder="info@noir36.com" className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="settings-email" />
                </div>
                <div>
                  <Label className="text-noir-text-sec text-xs uppercase tracking-wider">Indirizzo</Label>
                  <Input value={settings.address} onChange={(e) => setSettings({ ...settings, address: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="settings-address" />
                </div>
              </div>
            </div>

            {/* Save */}
            <motion.button
              onClick={handleSaveSettings}
              disabled={savingSettings}
              className="flex w-full items-center justify-center gap-2 rounded-full bg-noir-gold py-3 font-body text-sm font-semibold text-noir-base hover:bg-noir-gold-hover disabled:opacity-50"
              whileHover={{ scale: 1.02 }}
              whileTap={{ scale: 0.98 }}
              data-testid="settings-save-btn"
            >
              <Save size={14} /> {savingSettings ? "..." : "Salva Impostazioni"}
            </motion.button>
          </motion.div>
        )}
      </div>

      {/* Menu Item Edit/Create Modal */}
      <AnimatePresence>
        {showForm && (
          <motion.div className="fixed inset-0 z-50 flex items-end justify-center sm:items-center" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" onClick={() => setShowForm(false)} />
            <motion.div className="relative max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-t-2xl border border-noir-gold/20 bg-noir-surface p-6 sm:rounded-2xl" initial={{ y: 100, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 100, opacity: 0 }} data-testid="admin-item-form">
              <div className="mb-4 flex items-center justify-between">
                <h3 className="font-heading text-xl font-bold text-noir-text">{editingItem ? t.admin.editItem : t.admin.addItem}</h3>
                <button onClick={() => setShowForm(false)} className="text-noir-text-muted hover:text-noir-text" data-testid="admin-form-close"><X size={20} /></button>
              </div>
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-noir-text-sec text-xs uppercase tracking-wider">{t.admin.nameIt}</Label>
                    <Input value={formData.name_it} onChange={(e) => setFormData({ ...formData, name_it: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="admin-name-it" />
                  </div>
                  <div>
                    <Label className="text-noir-text-sec text-xs uppercase tracking-wider">{t.admin.nameEn}</Label>
                    <Input value={formData.name_en} onChange={(e) => setFormData({ ...formData, name_en: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="admin-name-en" />
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-noir-text-sec text-xs uppercase tracking-wider">{t.admin.descIt}</Label>
                    <Input value={formData.description_it} onChange={(e) => setFormData({ ...formData, description_it: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="admin-desc-it" />
                  </div>
                  <div>
                    <Label className="text-noir-text-sec text-xs uppercase tracking-wider">{t.admin.descEn}</Label>
                    <Input value={formData.description_en} onChange={(e) => setFormData({ ...formData, description_en: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="admin-desc-en" />
                  </div>
                </div>
                <div className="grid grid-cols-3 gap-3">
                  <div>
                    <Label className="text-noir-text-sec text-xs uppercase tracking-wider">{t.admin.priceLabel}</Label>
                    <Input type="number" step="0.01" value={formData.price} onChange={(e) => setFormData({ ...formData, price: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="admin-price" />
                  </div>
                  <div>
                    <Label className="text-noir-text-sec text-xs uppercase tracking-wider">{t.admin.priceBottle}</Label>
                    <Input type="number" step="0.01" value={formData.price_bottle} onChange={(e) => setFormData({ ...formData, price_bottle: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="admin-price-bottle" />
                  </div>
                  <div>
                    <Label className="text-noir-text-sec text-xs uppercase tracking-wider">{t.admin.order}</Label>
                    <Input type="number" value={formData.order} onChange={(e) => setFormData({ ...formData, order: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="admin-order" />
                  </div>
                </div>
                <div>
                  <Label className="text-noir-text-sec text-xs uppercase tracking-wider">{t.admin.category}</Label>
                  <Select value={formData.category} onValueChange={(v) => setFormData({ ...formData, category: v })}>
                    <SelectTrigger className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="admin-category-select"><SelectValue /></SelectTrigger>
                    <SelectContent className="border-noir-gold/20 bg-noir-surface text-noir-text">
                      {CATEGORIES.map((cat) => (<SelectItem key={cat} value={cat}>{t.categories[cat]}</SelectItem>))}
                    </SelectContent>
                  </Select>
                </div>
                <div>
                  <Label className="text-noir-text-sec text-xs uppercase tracking-wider">{t.menu.allergens}</Label>
                  <div className="mt-2 flex flex-wrap gap-2">
                    {ALLERGENS.map((a) => (
                      <button key={a} type="button" onClick={() => toggleAllergen(a)} className={`rounded-full px-3 py-1 text-xs transition-all ${formData.allergens.includes(a) ? "bg-noir-ember/20 text-noir-ember border border-noir-ember/40" : "border border-noir-gold/10 text-noir-text-muted hover:border-noir-gold/20"}`} data-testid={`admin-allergen-${a}`}>{t.allergens[a]}</button>
                    ))}
                  </div>
                </div>
                <div className="flex items-center gap-6">
                  <div className="flex items-center gap-2">
                    <Switch checked={formData.is_available} onCheckedChange={(v) => setFormData({ ...formData, is_available: v })} data-testid="admin-available-switch" />
                    <Label className="text-noir-text-sec text-xs">{t.admin.available}</Label>
                  </div>
                  <div className="flex items-center gap-2">
                    <Switch checked={formData.is_cocktail_of_day} onCheckedChange={(v) => setFormData({ ...formData, is_cocktail_of_day: v })} data-testid="admin-cocktail-of-day-switch" />
                    <Label className="text-noir-text-sec text-xs">{t.admin.cocktailOfDay}</Label>
                  </div>
                </div>
                <div className="flex gap-3 pt-2">
                  <motion.button onClick={handleSave} disabled={saving} className="flex flex-1 items-center justify-center gap-2 rounded-full bg-noir-gold py-2.5 font-body text-sm font-semibold text-noir-base hover:bg-noir-gold-hover disabled:opacity-50" whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }} data-testid="admin-save-button">
                    <Save size={14} /> {saving ? "..." : t.admin.save}
                  </motion.button>
                  <motion.button onClick={() => setShowForm(false)} className="rounded-full border border-noir-gold/15 px-5 py-2.5 text-sm text-noir-text-muted hover:text-noir-text" whileHover={{ scale: 1.02 }} data-testid="admin-cancel-button">{t.admin.cancel}</motion.button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Event Edit/Create Modal */}
      <AnimatePresence>
        {showEventForm && (
          <motion.div className="fixed inset-0 z-50 flex items-end justify-center sm:items-center" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            <div className="absolute inset-0 bg-black/70 backdrop-blur-sm" onClick={() => setShowEventForm(false)} />
            <motion.div className="relative max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-t-2xl border border-noir-gold/20 bg-noir-surface p-6 sm:rounded-2xl" initial={{ y: 100, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 100, opacity: 0 }} data-testid="admin-event-form">
              <div className="mb-4 flex items-center justify-between">
                <h3 className="font-heading text-xl font-bold text-noir-text">{editingEvent ? "Modifica Evento" : "Nuovo Evento"}</h3>
                <button onClick={() => setShowEventForm(false)} className="text-noir-text-muted hover:text-noir-text"><X size={20} /></button>
              </div>
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-noir-text-sec text-xs uppercase tracking-wider">Titolo (IT)</Label>
                    <Input value={eventForm.title_it} onChange={(e) => setEventForm({ ...eventForm, title_it: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="event-title-it" />
                  </div>
                  <div>
                    <Label className="text-noir-text-sec text-xs uppercase tracking-wider">Titolo (EN)</Label>
                    <Input value={eventForm.title_en} onChange={(e) => setEventForm({ ...eventForm, title_en: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="event-title-en" />
                  </div>
                </div>
                <div>
                  <Label className="text-noir-text-sec text-xs uppercase tracking-wider">Descrizione (IT)</Label>
                  <Input value={eventForm.description_it} onChange={(e) => setEventForm({ ...eventForm, description_it: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="event-desc-it" />
                </div>
                <div>
                  <Label className="text-noir-text-sec text-xs uppercase tracking-wider">Descrizione (EN)</Label>
                  <Input value={eventForm.description_en} onChange={(e) => setEventForm({ ...eventForm, description_en: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="event-desc-en" />
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <Label className="text-noir-text-sec text-xs uppercase tracking-wider">Data</Label>
                    <Input type="date" value={eventForm.date} onChange={(e) => setEventForm({ ...eventForm, date: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="event-date" />
                  </div>
                  <div>
                    <Label className="text-noir-text-sec text-xs uppercase tracking-wider">Ora</Label>
                    <Input type="time" value={eventForm.time} onChange={(e) => setEventForm({ ...eventForm, time: e.target.value })} className="mt-1 border-noir-gold/15 bg-noir-elevated text-noir-text" data-testid="event-time" />
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <Switch checked={eventForm.is_active} onCheckedChange={(v) => setEventForm({ ...eventForm, is_active: v })} data-testid="event-active-switch" />
                  <Label className="text-noir-text-sec text-xs">Visibile</Label>
                </div>
                <div className="flex gap-3 pt-2">
                  <motion.button onClick={handleSaveEvent} disabled={savingEvent} className="flex flex-1 items-center justify-center gap-2 rounded-full bg-noir-gold py-2.5 font-body text-sm font-semibold text-noir-base hover:bg-noir-gold-hover disabled:opacity-50" whileHover={{ scale: 1.02 }} data-testid="event-save-btn">
                    <Save size={14} /> {savingEvent ? "..." : "Salva"}
                  </motion.button>
                  <motion.button onClick={() => setShowEventForm(false)} className="rounded-full border border-noir-gold/15 px-5 py-2.5 text-sm text-noir-text-muted hover:text-noir-text" whileHover={{ scale: 1.02 }}>Annulla</motion.button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
