import { motion } from "framer-motion";
import { useLanguage } from "@/contexts/LanguageContext";
import { Filter, X } from "lucide-react";

const ALL_ALLERGENS = ["glutine", "lattosio", "frutta_a_guscio", "uova", "solfiti", "sesamo"];

export default function AllergenFilter({ activeFilters, onToggle, onClear }) {
  const { t } = useLanguage();

  return (
    <div className="flex flex-wrap items-center gap-2" data-testid="allergen-filter">
      <div className="flex items-center gap-1.5 text-noir-text-muted">
        <Filter size={14} />
        <span className="text-xs uppercase tracking-wider">{t.menu.filterAllergens}</span>
      </div>

      {ALL_ALLERGENS.map((allergen) => {
        const isActive = activeFilters.includes(allergen);
        return (
          <motion.button
            key={allergen}
            onClick={() => onToggle(allergen)}
            className={`
              rounded-full px-3 py-1 text-xs font-medium transition-all
              ${isActive
                ? "bg-noir-ember/20 text-noir-ember border border-noir-ember/40"
                : "border border-noir-gold/10 bg-noir-surface text-noir-text-muted hover:border-noir-gold/20 hover:text-noir-text-sec"
              }
            `}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            data-testid={`allergen-filter-${allergen}`}
          >
            {t.allergens[allergen] || allergen}
          </motion.button>
        );
      })}

      {activeFilters.length > 0 && (
        <motion.button
          onClick={onClear}
          className="flex items-center gap-1 rounded-full bg-noir-elevated px-2 py-1 text-xs text-noir-text-muted hover:text-noir-text"
          initial={{ scale: 0 }}
          animate={{ scale: 1 }}
          data-testid="allergen-filter-clear"
        >
          <X size={12} />
        </motion.button>
      )}
    </div>
  );
}
