import { useRef, useState, useEffect, useCallback } from "react";
import { useScroll, useTransform, useMotionValueEvent, useSpring } from "framer-motion";

const TOTAL_FRAMES = 151;

function usePreloadFrames() {
  const [images, setImages] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    let cancelled = false;
    const imgs = [];
    let count = 0;

    for (let i = 1; i <= TOTAL_FRAMES; i++) {
      const img = new Image();
      img.src = `/frames/frame-${String(i).padStart(3, "0")}.jpg`;
      img.onload = () => {
        count++;
        if (!cancelled) setProgress(Math.round((count / TOTAL_FRAMES) * 100));
        if (count === TOTAL_FRAMES && !cancelled) setLoaded(true);
      };
      img.onerror = () => {
        count++;
        if (count === TOTAL_FRAMES && !cancelled) setLoaded(true);
      };
      imgs.push(img);
    }
    setImages(imgs);
    return () => { cancelled = true; };
  }, []);

  return { images, loaded, progress };
}

export default function ScrollFrames() {
  const containerRef = useRef(null);
  const canvasRef = useRef(null);
  const lastFrameRef = useRef(-1);
  const { images, loaded, progress } = usePreloadFrames();

  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start start", "end end"],
  });

  // Spring-smoothed scroll for buttery transitions
  const smoothProgress = useSpring(scrollYProgress, {
    stiffness: 120,
    damping: 30,
    mass: 0.5,
  });

  const frameIndex = useTransform(smoothProgress, [0, 1], [0, TOTAL_FRAMES - 1]);

  const renderFrame = useCallback(
    (index) => {
      const canvas = canvasRef.current;
      if (!canvas || !images.length) return;

      const idx = Math.round(index);
      if (idx === lastFrameRef.current) return; // skip if same frame
      lastFrameRef.current = idx;

      const ctx = canvas.getContext("2d");
      const img = images[idx];
      if (!img || !img.complete) return;

      const cw = canvas.width;
      const ch = canvas.height;
      const iw = img.naturalWidth;
      const ih = img.naturalHeight;
      const scale = Math.max(cw / iw, ch / ih);
      const sw = iw * scale;
      const sh = ih * scale;
      const sx = (cw - sw) / 2;
      const sy = (ch - sh) / 2;

      ctx.clearRect(0, 0, cw, ch);
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = "high";
      ctx.drawImage(img, sx, sy, sw, sh);
    },
    [images]
  );

  useMotionValueEvent(frameIndex, "change", (v) => renderFrame(v));

  useEffect(() => {
    const resize = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = window.innerWidth * dpr;
      canvas.height = window.innerHeight * dpr;
      canvas.style.width = window.innerWidth + "px";
      canvas.style.height = window.innerHeight + "px";
      lastFrameRef.current = -1; // force re-render
      renderFrame(frameIndex.get());
    };
    resize();
    window.addEventListener("resize", resize);
    return () => window.removeEventListener("resize", resize);
  }, [renderFrame, frameIndex]);

  useEffect(() => {
    if (loaded) renderFrame(0);
  }, [loaded, renderFrame]);

  return (
    <div
      ref={containerRef}
      data-testid="scroll-frames-container"
      style={{ height: `${TOTAL_FRAMES * 18}px` }}
    >
      <div className="sticky top-0 h-screen w-screen overflow-hidden">
        {!loaded && (
          <div className="flex h-full flex-col items-center justify-center gap-3 bg-noir-base">
            <div className="h-8 w-8 animate-spin rounded-full border-2 border-noir-gold/30 border-t-noir-gold" />
            <span className="text-xs text-noir-text-muted font-body tracking-wider">{progress}%</span>
          </div>
        )}
        <canvas
          ref={canvasRef}
          className="block"
          style={{ display: loaded ? "block" : "none" }}
        />
      </div>
    </div>
  );
}
